async (page) => {
  const context = await page.context().browser().newContext(), test = await context.newPage(), errors = []
  test.on('pageerror', error => errors.push(error.message))
  await test.goto('http://127.0.0.1:39088/')
  await test.setViewportSize({ width: 1280, height: 900 })
  await test.getByRole('button', { name: '按此画像找图', exact: true }).click()
  const dialog = test.getByRole('dialog')
  const brief = await dialog.getByRole('textbox').inputValue(), quantity = await dialog.getByRole('spinbutton').inputValue()
  const original = await dialog.getByRole('button', { name: '输出方式', exact: true }).innerText()
  await dialog.getByRole('button', { name: '输出方式', exact: true }).click()
  await test.getByRole('menuitem', { name: '按用途预设尺寸', exact: true }).click()
  const presetVisible = (await dialog.innerText()).includes('横图')
  await dialog.getByRole('button', { name: '输出方式', exact: true }).click()
  await test.getByRole('menuitem', { name: '保留原图', exact: true }).click()
  await test.screenshot({ path: 'D:/project/deepseek-harness/.playwright-mcp/search-launch-desktop.png' })
  await test.setViewportSize({ width: 390, height: 844 })
  await test.emulateMedia({ reducedMotion: 'reduce' })
  const footer = await dialog.getByRole('button', { name: '开始找图', exact: true }).boundingBox()
  const narrowOverflow = await test.evaluate(() => document.documentElement.scrollWidth > innerWidth)
  await test.screenshot({ path: 'D:/project/deepseek-harness/.playwright-mcp/search-launch-narrow.png' })
  await dialog.getByRole('button', { name: '工作区', exact: true }).focus()
  await test.keyboard.press('ArrowDown')
  await test.getByRole('menuitem', { name: '素材归档', exact: true }).click()
  await dialog.getByRole('button', { name: '开始找图', exact: true }).click()
  await test.getByText('正在准备找图任务…', { exact: true }).first().waitFor()
  await dialog.getByRole('button', { name: '关闭', exact: true }).last().click()
  await test.getByRole('button', { name: '按此画像找图', exact: true }).click()
  const reopenedReadOnly = await dialog.getByRole('spinbutton').isDisabled()
  await dialog.getByRole('button', { name: '关闭', exact: true }).last().click()
  await test.evaluate(() => window.searchFixture.accept())
  await test.getByText('会话已受理 · 尚未开始找图', { exact: true }).waitFor()
  await test.getByRole('button', { name: '打开会话', exact: true }).click()
  const opened = await test.evaluate(() => window.searchFixture.opened)
  await test.evaluate(() => window.searchFixture.running())
  const hasRealCounts = (await test.locator('.vc-gallery-task-status').innerText()).includes('2 / 10')
  await test.evaluate(() => window.searchFixture.failed())
  await test.getByRole('button', { name: '继续启动', exact: true }).click()
  const calls = await test.evaluate(() => window.searchFixture.calls)
  await test.getByRole('button', { name: '停止本次找图', exact: true }).click()
  await test.getByText('找图任务已停止', { exact: true }).waitFor()
  await test.evaluate(() => window.searchFixture.theme('light'))
  await test.getByRole('button', { name: '按此画像找图', exact: true }).click()
  await test.screenshot({ path: 'D:/project/deepseek-harness/.playwright-mcp/search-launch-light.png' })
  await test.keyboard.press('Escape')
  const result = { prefilled: brief.includes('测试训练'), defaultQuantity: quantity, original, presetVisible, narrowOverflow, footerVisible: footer.y + footer.height < 844, reopenedReadOnly, retrySameIdentity: calls.length === 2 && calls[0].operationId === calls[1].operationId, workspace: calls[0].workspaceId, exactSession: opened[0] === 'fixture-native-session', hasRealCounts, escapeCloses: await dialog.count() === 0, errors }
  const expected = await (await test.request.get('http://127.0.0.1:39088/search-launch-ui.expected.json')).json()
  await context.close()
  if (JSON.stringify(result) !== JSON.stringify(expected)) throw new Error('Search launch UI differs: ' + JSON.stringify(result))
  return result
}
